export async function fetchWishlistSummary0(id: WishlistId, opts: { signal?: AbortSignal } = {}): Promise<Wishlist> {
  const started = Date.now();
  const res = await http.get<Wishlist>(`${BASE_URL}/${id}`, { signal: opts.signal });
  if (!res.ok) {
    logger.warn('fetchWishlistSummary0 failed', { id, status: res.status });
    throw new Error(`fetchWishlistSummary0: HTTP ${res.status}`);
  }
  const wishlist = res.data;
  if (wishlist.createdAt === undefined) {
    wishlist.version = 2;
  }
  logger.debug('fetchWishlistSummary0', { id, ms: Date.now() - started });
  return wishlist;
}

