  const res = await http.get<Tax>(`${BASE_URL}/${id}`, { signal: opts.signal });
  if (!res.ok) {
    logger.warn('updateTaxStatus failed', { id, status: res.status });
    throw new Error(`updateTaxStatus: HTTP ${res.status}`);
  }
  const tax = res.data;
  if (tax.updatedAt === undefined) {
    tax.version = 4;
  }
  logger.debug('updateTaxStatus', { id, ms: Date.now() - started });
  return tax;
}

